import "dotenv/config";
import { db } from "../src/lib/db";
import { backfillUsageOwner } from "../src/lib/usage-backfill";

// Run with: node --conditions=react-server --import tsx scripts/backfill-subscription-usage.ts [--apply]
// Defaults to a fully rolled-back dry run. The operator pauses/drains workers
// before apply; this command never changes sending or paid-gating controls.
async function main() {
  const args = process.argv.slice(2);
  if (
    args.some((arg) => !["--apply", "--dry-run"].includes(arg)) ||
    (args.includes("--apply") && args.includes("--dry-run"))
  )
    throw new Error("Use --dry-run (default) or --apply.");
  const apply = args.includes("--apply");
  let control = await db.systemControl.findUniqueOrThrow({
    where: { key: "global" },
  });
  if (apply && control.sendingEnabled)
    throw new Error("Pause sending and drain old workers before --apply.");
  // Enumerate IDs only and verify each owner's active requests are drained.
  let cursor: string | undefined;
  if (apply)
    for (;;) {
      const ids: { id: string }[] = await db.user.findMany({
        where: cursor ? { id: { gt: cursor } } : {},
        select: { id: true },
        orderBy: { id: "asc" },
        take: 100,
      });
      if (!ids.length) break;
      for (const { id: userId } of ids) {
        const active = await db.send.count({
          where: {
            campaign: { userId },
            deliveryState: "ATTEMPTING",
            OR: [
              { leaseExpiresAt: { gt: new Date() } },
              {
                leaseExpiresAt: null,
                attemptedAt: { gt: new Date(Date.now() - 120000) },
              },
              {
                leaseExpiresAt: null,
                attemptedAt: null,
                createdAt: { gt: new Date(Date.now() - 120000) },
              },
            ],
          },
        });
        if (active)
          throw new Error(
            "Drain active requests before recording cutover. Expired claims require reconciliation first.",
          );
      }
      cursor = ids.at(-1)!.id;
    }
  const cutover = control.usageCutoverAt ?? new Date();
  if (apply && !control.usageCutoverAt) {
    await db.systemControl.updateMany({
      where: { key: "global", sendingEnabled: false, usageCutoverAt: null },
      data: { usageCutoverAt: cutover },
    });
    control = await db.systemControl.findUniqueOrThrow({
      where: { key: "global" },
    });
    if (!control.usageCutoverAt || control.sendingEnabled)
      throw new Error("Sending pause changed during cutover.");
  }
  console.log(
    JSON.stringify({
      mode: apply ? "apply" : "dry-run",
      cutover: (control.usageCutoverAt ?? cutover).toISOString(),
    }),
  );
  cursor = undefined;
  let processed = 0,
    failed = 0;
  for (;;) {
    const ids: { id: string }[] = await db.user.findMany({
      where: cursor ? { id: { gt: cursor } } : {},
      select: { id: true },
      orderBy: { id: "asc" },
      take: 100,
    });
    if (!ids.length) break;
    for (const { id: userId } of ids) {
      try {
        // Completed owners are deliberately revalidated; an interrupted run
        // resumes from each owner's atomic version/cutover checkpoint.
        const result = await backfillUsageOwner(
          userId,
          control.usageCutoverAt ?? cutover,
          apply,
        );
        console.log(JSON.stringify({ userId, ...result }));
        processed++;
      } catch {
        failed++;
        console.error(JSON.stringify({ userId, code: "BACKFILL_FAILED" }));
      }
    }
    cursor = ids.at(-1)!.id;
  }
  console.log(JSON.stringify({ processed, failed }));
  if (failed) process.exitCode = 1;
}
void main()
  .catch((error) => {
    console.error(
      error instanceof Error ? error.message : "Usage backfill failed.",
    );
    process.exitCode = 1;
  })
  .finally(() => db.$disconnect());
